entries[62289] = { ["name"] = "Gebratenes Drachenfestmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Drachenfestmahl her! Stellt im Verlauf von 30 Sek. 6510 Gesundheit und ( 1118 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 9 Ausdauer und ein für Euch nützlicher Wert wird um 9 erhöht.\nVerkaufspreis:" }
entries[62290] = { ["name"] = "Meeresfrüchtefestmahl Magnifique", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Meeresfrüchtefestmahl Magnifique her! Stellt im Verlauf von 30 Sek. 8944 Gesundheit und ( 1375 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 15 Ausdauer und ein für Euch nützlicher Wert wird um 15 erhöht.\nVerkaufspreis:" }
entries[62298] = { ["name"] = "Zügel des Goldkönigs", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört den Goldkönig oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Lasst Euch nicht vom Sattel täuschen, er ist wild und kein zahmer Löwe.\"\nVerkäufer:\nWeltverkäufer\nKosten:" }
